// include common definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (TMAX, NX, NY, etc.)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize arrays using Halide Funcs, mirroring the original C init_array.
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    // _fict_[t] = t;
    {
        Func init_fict("init_fict");
        init_fict(t) = cast<num_t>(t);
        init_fict.realize(fict);
    }

    // Note: C arrays are ex[i][j] with i in [0..nx-1], j in [0..ny-1].
    // Halide buffers are ex(j, i) with shape (ny, nx).
    Expr nx_expr = cast<num_t>(nx);
    Expr ny_expr = cast<num_t>(ny);

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz");

    // ex[i][j] = (i * (j+1)) / nx;
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / nx_expr;

    // ey[i][j] = (i * (j+2)) / ny;
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / ny_expr;

    // hz[i][j] = (i * (j+3)) / nx;
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / nx_expr;

    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int tmax = TMAX;
    int nx = NX;
    int ny = NY;

    // Allocate data buffers.
    // C layout: ex[nx][ny] -> Halide: ex(width=ny, height=nx)
    Halide::Buffer<num_t, 2> ex_curr(ny, nx);  // (j, i)
    Halide::Buffer<num_t, 2> ey_curr(ny, nx);
    Halide::Buffer<num_t, 2> hz_curr(ny, nx);
    Halide::Buffer<num_t, 1> fict(tmax);

    // Double buffers for the time stepping.
    Halide::Buffer<num_t, 2> ex_next(ny, nx);
    Halide::Buffer<num_t, 2> ey_next(ny, nx);
    Halide::Buffer<num_t, 2> hz_next(ny, nx);

    // Initialize arrays.
    init_array(tmax, nx, ny, ex_curr, ey_curr, hz_curr, fict);

    // --------------------------------------------------------------------
    // Build Halide step kernels corresponding to one time iteration.
    // We follow the rules: each step Func reads only from ImageParams
    // (no illegal self-references), and the outer time loop is in C++.
    // --------------------------------------------------------------------

    Var j("j"), i("i");

    // --------------------------------------------------------------------
    // First and second updates in the C kernel:
    //
    // for (j = 0; j < ny; j++)
    //   ey[0][j] = _fict_[t];
    // for (i = 1; i < nx; i++)
    //   for (j = 0; j < ny; j++)
    //     ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // for (i = 0; i < nx; i++)
    //   for (j = 1; j < ny; j++)
    //     ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // These become two elementwise transforms:
    //   ey_step(ex_in, ey_in, hz_in, fict_t) -> ey_out
    //   ex_step(ex_in, ey_in, hz_in, fict_t) -> ex_out
    // --------------------------------------------------------------------

    ImageParam ex_in(type_of<num_t>(), 2, "ex_in");
    ImageParam ey_in(type_of<num_t>(), 2, "ey_in");
    ImageParam hz_in(type_of<num_t>(), 2, "hz_in");
    Param<num_t> fict_t("fict_t");

    Expr half = cast<num_t>(0.5f);

    // Boundary-safe version of hz_in for neighbor access (repeat-edge).
    Func hz_bc("hz_bc");
    hz_bc(j, i) = hz_in(clamp(j, 0, ny - 1),
                        clamp(i, 0, nx - 1));

    // ey_step: compute ey at next time step
    // ey_new[i][j] = (i == 0) ? _fict_[t] :
    //                 ey_old[i][j] - 0.5 * (hz_old[i][j] - hz_old[i-1][j])
    //
    // Mapping: ey[i][j] -> ey_in(j, i), hz[i][j] -> hz_bc(j, i)
    Func ey_step("ey_step");
    ey_step(j, i) = select(i == 0,
                           fict_t,
                           ey_in(j, i) -
                               half * (hz_bc(j, i) - hz_bc(j, i - 1)));

    // ex_step: compute ex at next time step
    // ex_new[i][j] = (j == 0) ? ex_old[i][j] :
    //                 ex_old[i][j] - 0.5 * (hz_old[i][j] - hz_old[i][j-1])
    //
    // Mapping: ex[i][j] -> ex_in(j, i), hz[i][j] -> hz_bc(j, i)
    Func ex_step("ex_step");
    ex_step(j, i) = select(j == 0,
                           ex_in(j, i),
                           ex_in(j, i) -
                               half * (hz_bc(j, i) - hz_bc(j - 1, i)));

    // --------------------------------------------------------------------
    // Third update in the C kernel:
    //
    // for (i = 0; i < nx - 1; i++)
    //   for (j = 0; j < ny - 1; j++)
    //     hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j] +
    //                        ey[i+1][j] - ey[i][j]);
    //
    // This becomes hz_step(ex_new, ey_new, hz_old) -> hz_out.
    // We'll compute ex_new, ey_new into Buffers, then feed them as inputs
    // to hz_step via ImageParams.
    // --------------------------------------------------------------------

    ImageParam ex_new_in(type_of<num_t>(), 2, "ex_new_in");
    ImageParam ey_new_in(type_of<num_t>(), 2, "ey_new_in");
    ImageParam hz_old_in(type_of<num_t>(), 2, "hz_old_in");

    // Boundary-safe versions of ex_new and ey_new for neighbor access
    Func ex_new_bc("ex_new_bc"), ey_new_bc("ey_new_bc");
    ex_new_bc(j, i) = ex_new_in(clamp(j, 0, ny - 1),
                                clamp(i, 0, nx - 1));
    ey_new_bc(j, i) = ey_new_in(clamp(j, 0, ny - 1),
                                clamp(i, 0, nx - 1));

    Expr seven_tenths = cast<num_t>(0.7f);

    // hz_step: compute hz at next time step
    // For interior:   hz_new = hz_old - 0.7 * (...)
    // For last row/col: keep old value (same as not updating).
    Func hz_step("hz_step");
    hz_step(j, i) =
        select((i < nx - 1) && (j < ny - 1),
               hz_old_in(j, i) -
                   seven_tenths *
                       ((ex_new_bc(j + 1, i) - ex_new_bc(j, i)) +
                        (ey_new_bc(j, i + 1) - ey_new_bc(j, i))),
               hz_old_in(j, i));

    // Simple scheduling: compute everything at root, row-major order.
    ey_step.compute_root().reorder(j, i);
    ex_step.compute_root().reorder(j, i);
    hz_step.compute_root().reorder(j, i);

    // JIT-compile the step kernels once.
    ey_step.compile_jit();
    ex_step.compile_jit();
    hz_step.compile_jit();

    // --------------------------------------------------------------------
    // Time-stepping loop, driven from the host.
    // We use double buffering on ex, ey, hz, as required for a DP-like update.
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tmax; ++t) {
        // Bind inputs for ey_step and ex_step
        ex_in.set(ex_curr);
        ey_in.set(ey_curr);
        hz_in.set(hz_curr);
        fict_t.set(fict(t));

        // Compute ey_next and ex_next
        ey_step.realize(ey_next);
        ex_step.realize(ex_next);

        // Bind inputs for hz_step: hz_old, ex_new, ey_new
        ex_new_in.set(ex_next);
        ey_new_in.set(ey_next);
        hz_old_in.set(hz_curr);

        // Compute hz_next
        hz_step.realize(hz_next);

        // Swap current and next buffers for the next time step
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print out the results (similar to print_array in C version).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        std::cerr << "ex:\n";
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                if (((i * nx + j) % 20) == 0) {
                    std::cerr << '\n';
                }
                std::cerr << ex_curr(j, i) << ' ';
            }
        }
        std::cerr << "\n\ney:\n";
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                if (((i * nx + j) % 20) == 0) {
                    std::cerr << '\n';
                }
                std::cerr << ey_curr(j, i) << ' ';
            }
        }
        std::cerr << "\n\nhz:\n";
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                if (((i * nx + j) % 20) == 0) {
                    std::cerr << '\n';
                }
                std::cerr << hz_curr(j, i) << ' ';
            }
        }
        std::cerr << '\n';
    }

    // Print timing (seconds, with microsecond precision).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
