#include <chrono>
#include <iomanip>
#include <iostream>
#include <utility>
#include <vector>

#include "Halide.h"

// include common definitions (DATA_TYPE, TMAX, NX, NY, SCALAR_VAL, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization, translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < tmax; i++)
 *     _fict_[i] = (DATA_TYPE) i;
 *   for (i = 0; i < nx; i++)
 *     for (j = 0; j < ny; j++) {
 *       ex[i][j] = ((DATA_TYPE) i*(j+1)) / nx;
 *       ey[i][j] = ((DATA_TYPE) i*(j+2)) / ny;
 *       hz[i][j] = ((DATA_TYPE) i*(j+3)) / nx;
 *     }
 *
 * Mapping to Halide Buffers:
 *   C 2D arrays ex[i][j], ey[i][j], hz[i][j]  (i: 0..nx-1, j: 0..ny-1)
 *   -> Halide Buffer<num_t,2> with shape (ny, nx), accessed as (j, i).
 *   C 1D array _fict_[t] (t: 0..tmax-1)
 *   -> Halide Buffer<num_t,1> with shape (tmax), accessed as (t).
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j");

    Func init_fict("init_fict");
    Func init_ex("init_ex");
    Func init_ey("init_ey");
    Func init_hz("init_hz");

    // _fict_[t] = t
    init_fict(i) = cast<num_t>(i);

    // ex[i][j] = (i * (j + 1)) / nx
    // ey[i][j] = (i * (j + 2)) / ny
    // hz[i][j] = (i * (j + 3)) / nx
    //
    // Remember: Buffer layout is (j, i) => (x, y) = (j, i).
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<num_t>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<num_t>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<num_t>(nx);

    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from PolyBench definitions).
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for fields.
    // Mapping: C ex[i][j] -> ex(j, i), with shape (ny, nx).
    Halide::Buffer<num_t, 2> ex_curr(ny, nx);
    Halide::Buffer<num_t, 2> ey_curr(ny, nx);
    Halide::Buffer<num_t, 2> hz_curr(ny, nx);

    // Buffers for next time step (double buffering).
    Halide::Buffer<num_t, 2> ex_next(ny, nx);
    Halide::Buffer<num_t, 2> ey_next(ny, nx);
    Halide::Buffer<num_t, 2> hz_next(ny, nx);

    // 1D buffer for fictitious boundary values.
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize data.
    init_array(tmax, nx, ny, ex_curr, ey_curr, hz_curr, fict);

    // -------------------------------------------------------------------------
    // Define Halide pipeline for a single time step of FDTD-2D.
    //
    // Original C kernel for one time-step (t):
    //
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5*(hz[i][j] - hz[i-1][j]);
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5*(hz[i][j] - hz[i][j-1]);
    //   for (i = 0; i < nx-1; i++)
    //     for (j = 0; j < ny-1; j++)
    //       hz[i][j] = hz[i][j] - 0.7*(ex[i][j+1] - ex[i][j]
    //                                 + ey[i+1][j] - ey[i][j]);
    //
    // We implement a single time-step as a Halide pipeline that:
    //   - Takes ex_curr, ey_curr, hz_curr, fict, and t as inputs
    //   - Produces ex_next, ey_next, hz_next as outputs
    //
    // Time-stepping over t is done on the host (double-buffering),
    // to avoid illegal self-referential Halide updates across time.
    // -------------------------------------------------------------------------

    // Image parameters for current state and fictitious boundary.
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");
    ImageParam fict_param(type_of<num_t>(), 1, "fict_param");

    // Scalar parameter for current time index t.
    Param<int> t("t");

    Var x("x"), y("y");

    // Wrap hz with a boundary condition so stencil accesses are always in-bounds,
    // even for y-1, x-1, etc. This satisfies Halide's bounds analysis.
    Func hz_padded("hz_padded");
    hz_padded = Halide::BoundaryConditions::repeat_edge(hz_param);

    // -------------------------------------------------------------------------
    // 1) Update ey: ey_next
    //
    // ey[0][j] = fict[t];
    // ey[i][j] = ey[i][j] - 0.5*(hz[i][j] - hz[i-1][j])   for i >= 1
    //
    // Mapping: ey[i][j] -> ey_param(j, i)  => indices (x = j, y = i)
    //           hz[i][j] -> hz_param(j, i)
    // -------------------------------------------------------------------------
    Func ey_update("ey_update");

    Expr fict_t = fict_param(t);

    ey_update(x, y) = select(
        y == 0,
        // i == 0 row: ey[0][j] = fict[t]
        fict_t,
        // i >= 1 rows:
        ey_param(x, y) - cast<num_t>(0.5f) *
                             (hz_padded(x, y) - hz_padded(x, y - 1)));

    // -------------------------------------------------------------------------
    // 2) Update ex: ex_next
    //
    // ex[i][j] = ex[i][j] - 0.5*(hz[i][j] - hz[i][j-1])   for j >= 1
    // ex[i][0] unchanged
    //
    // Mapping: ex[i][j] -> ex_param(j, i)
    //           hz[i][j] -> hz_param(j, i)
    // -------------------------------------------------------------------------
    Func ex_update("ex_update");

    ex_update(x, y) = select(
        x == 0,
        // j == 0 column: ex[i][0] unchanged.
        ex_param(x, y),
        // j >= 1:
        ex_param(x, y) - cast<num_t>(0.5f) *
                             (hz_padded(x, y) - hz_padded(x - 1, y)));

    // For hz update we need ex[i][j+1], ex[i][j], ey[i+1][j], ey[i][j],
    // i.e., ex_update(x+1,y), ex_update(x,y), ey_update(x,y+1), ey_update(x,y).
    // Wrap ex_update and ey_update with boundary conditions for safety.
    Func ex_padded("ex_padded");
    ex_padded = Halide::BoundaryConditions::repeat_edge(ex_update);

    Func ey_padded("ey_padded");
    ey_padded = Halide::BoundaryConditions::repeat_edge(ey_update);

    // -------------------------------------------------------------------------
    // 3) Update hz: hz_next
    //
    // for (i = 0; i < nx-1; i++)
    //   for (j = 0; j < ny-1; j++)
    //     hz[i][j] = hz[i][j] - 0.7 * ((ex[i][j+1]-ex[i][j])
    //                                  + (ey[i+1][j]-ey[i][j]));
    // Boundary i == nx-1 or j == ny-1 remain unchanged.
    //
    // Mapping: hz[i][j]   -> hz_param(j, i)
    //          ex[i][j+1] -> ex_update(j+1, i)
    //          ex[i][j]   -> ex_update(j,   i)
    //          ey[i+1][j] -> ey_update(j,   i+1)
    //          ey[i][j]   -> ey_update(j,   i)
    // -------------------------------------------------------------------------
    Func hz_update("hz_update");

    Expr width  = hz_param.dim(0).extent();  // ny
    Expr height = hz_param.dim(1).extent();  // nx

    Expr ex_diff = ex_padded(x + 1, y) - ex_padded(x, y);
    Expr ey_diff = ey_padded(x, y + 1) - ey_padded(x, y);

    Expr interior = hz_param(x, y) - cast<num_t>(0.7f) * (ex_diff + ey_diff);

    hz_update(x, y) = select(
        (x < width - 1) && (y < height - 1),
        interior,
        // Boundary cells (last row/col) remain unchanged.
        hz_param(x, y));

    // Collect all three updated fields as pipeline outputs.
    std::vector<Func> outputs = {ex_update, ey_update, hz_update};
    Pipeline fdtd_step(outputs);

    // Compile the kernel to machine code, once.
    fdtd_step.compile_jit();

    // -------------------------------------------------------------------------
    // Time-stepping loop, measured.
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // fict is constant over time; set it once.
    fict_param.set(fict);

    for (int tt = 0; tt < tmax; ++tt) {
        // Bind current state as input.
        ex_param.set(ex_curr);
        ey_param.set(ey_curr);
        hz_param.set(hz_curr);

        // Current fict index.
        t.set(tt);

        // Realize updated fields into ex_next / ey_next / hz_next.
        Realization r({ex_next, ey_next, hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next time step.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (mainly to prevent dead-code elimination
    // and to loosely mimic the PolyBench print_array behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_curr(j, i) << '\n';
            }
        }
        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_curr(j, i) << '\n';
            }
        }
        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_curr(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds, as in the GEMM example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
