 *
 * C layout:
 *   ex[nx][ny], ey[nx][ny], hz[nx][ny], _fict_[tmax]
 *
 * Halide layout:
 *   Buffer<num_t,2> ex(ny, nx) accessed as ex(j, i) <-> ex[i][j]
 *   Buffer<num_t,2> ey(ny, nx)
 *   Buffer<num_t,2> hz(ny, nx)
 *   Buffer<num_t,1> fict(tmax) accessed as fict(t) <-> _fict_[t]
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    // _fict_[i] = i;
    Func init_fict("init_fict");
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: ex(j, i) corresponds to ex[i][j].
    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz");

    init_ex(j, i) =
        cast<num_t>((i * (j + 1) % nx)) / cast<int>(nx);

    init_ey(j, i) =
        cast<num_t>((i * (j + 2) % ny)) / cast<int>(ny);

    init_hz(j, i) =
        cast<num_t>((i * (j + 3) % nx)) / cast<int>(nx);

    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem size
    const int tmax = TMAX;
    const int nx   = NX;
    const int ny   = NY;

    // Buffers corresponding to C arrays:
    // C: ex[nx][ny] -> Halide: ex(ny, nx)
    Halide::Buffer<num_t, 2> ex_curr(ny, nx);
    Halide::Buffer<num_t, 2> ey_curr(ny, nx);
    Halide::Buffer<num_t, 2> hz_curr(ny, nx);

    Halide::Buffer<num_t, 2> ex_next(ny, nx);
    Halide::Buffer<num_t, 2> ey_next(ny, nx);
    Halide::Buffer<num_t, 2> hz_next(ny, nx);

    // _fict_[tmax] -> Halide: fict(tmax)
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize data
    init_array(tmax, nx, ny, ex_curr, ey_curr, hz_curr, fict);

    // Declare ImageParams for the previous time-step fields
    ImageParam ex_prev(type_of<num_t>(), 2, "ex_prev");
    ImageParam ey_prev(type_of<num_t>(), 2, "ey_prev");
    ImageParam hz_prev(type_of<num_t>(), 2, "hz_prev");
    ImageParam fict_param(type_of<num_t>(), 1, "fict_param");

    // Time index parameter
    Param<int> t_param("t");

    // Vars and reduction domains
    Var x("x"), y("y");

    // Constants that match SCALAR_VAL(0.5) and SCALAR_VAL(0.7)
    Expr half = Expr((float)0.5f);
    Expr seven_tenths = Expr((float)0.7f);

    // Next-step fields
    Func ey_next_func("ey_next_func");
    Func ex_next_func("ex_next_func");
    Func hz_next_func("hz_next_func");

    // =======================
    // ey update
    // =======================
    //
    // Original C:
    //   for (j = 0; j < NY; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < NX; i++)
    //     for (j = 0; j < NY; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Mapping to Halide:
    //   y = i in [0, nx-1], x = j in [0, ny-1]
    //   ey_prev(x, y)  <-> ey[i][j]
    //   hz_prev(x, y)  <-> hz[i][j]
    //   hz_prev(x, y-1)<-> hz[i-1][j]
    //
    // 1) Start by copying previous ey.
    ey_next_func(x, y) = ey_prev(x, y);

    // 2) Apply boundary: ey[0][j] = _fict_[t], i.e. y == 0
    {
        RDom rj(0, ny, "rj"); // x = j in [0, ny-1]
        ey_next_func(rj.x, 0) = fict_param(t_param);
    }

    // 3) Update interior rows: i >= 1 => y in [1, nx-1]
    {
        RDom r1(0, ny,   // x in [0, ny-1]
                1, nx-1, // y in [1, nx-1]
                "r1");
        ey_next_func(r1.x, r1.y) =
            ey_next_func(r1.x, r1.y) -
            half * (hz_prev(r1.x, r1.y) - hz_prev(r1.x, r1.y - 1));
    }

    // =======================
    // ex update
    // =======================
    //
    // Original C:
    //   for (i = 0; i < NX; i++)
    //     for (j = 1; j < NY; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Mapping:
    //   ex_prev(x, y)     <-> ex[i][j]
    //   hz_prev(x, y)     <-> hz[i][j]
    //   hz_prev(x-1, y)   <-> hz[i][j-1]
    //
    // 1) Copy previous ex.
    ex_next_func(x, y) = ex_prev(x, y);

    // 2) Update columns j >= 1 => x in [1, ny-1]
    {
        RDom r2(1, ny - 1, // x in [1, ny-1]
                0, nx,     // y in [0, nx-1]
                "r2");
        ex_next_func(r2.x, r2.y) =
            ex_next_func(r2.x, r2.y) -
            half * (hz_prev(r2.x, r2.y) - hz_prev(r2.x - 1, r2.y));
    }

    // =======================
    // hz update
    // =======================
    //
    // Original C:
    //   for (i = 0; i < NX - 1; i++)
    //     for (j = 0; j < NY - 1; j++)
    //       hz[i][j] = hz[i][j] -
    //                  0.7 * (ex[i][j+1] - ex[i][j] +
    //                         ey[i+1][j] - ey[i][j]);
    //
    // Mapping:
    //   hz_prev(x, y)     <-> hz[i][j]
    //   ex_next(x, y)     <-> ex[i][j]
    //   ex_next(x+1, y)   <-> ex[i][j+1]
    //   ey_next(x, y)     <-> ey[i][j]
    //   ey_next(x, y+1)   <-> ey[i+1][j]
    //
    // 1) Copy previous hz.
    hz_next_func(x, y) = hz_prev(x, y);

    // 2) Update interior region: i in [0, nx-2], j in [0, ny-2]
    {
        RDom r3(0, ny - 1, // x in [0, ny-2]
                0, nx - 1, // y in [0, nx-2]
                "r3");
        hz_next_func(r3.x, r3.y) =
            hz_next_func(r3.x, r3.y) -
            seven_tenths *
                (ex_next_func(r3.x + 1, r3.y) - ex_next_func(r3.x, r3.y) +
                 ey_next_func(r3.x, r3.y + 1) - ey_next_func(r3.x, r3.y));
    }

    // We will treat ex_next_func, ey_next_func, hz_next_func as the outputs
    // of a single time-step pipeline.
    Pipeline step_pipeline({ex_next_func, ey_next_func, hz_next_func});

    // Bind the time-invariant ImageParam for _fict_.
    fict_param.set(fict);

    // Compile the pipeline once (JIT)
    step_pipeline.compile_jit();

    // Time-stepping loop
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tmax; t++) {
        // Bind previous-step fields and current time index
        ex_prev.set(ex_curr);
        ey_prev.set(ey_curr);
        hz_prev.set(hz_curr);
        t_param.set(t);

        // Compute next-step fields
        step_pipeline.realize({ex_next, ey_next, hz_next});

        // Swap current and next buffers (double buffering)
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
