    // Second: for i >= 1 (y >= 1): ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])
    RDom rey(0, ey_in.dim(0).extent(),        // x: 0 .. ny-1
             1, ey_in.dim(1).extent() - 1,    // y: 1 .. nx-1
             "rey");
    ey_updated(rey.x, rey.y) =
        ey_updated(rey.x, rey.y) -
        half * (hz_in(rey.x, rey.y) - hz_in(rey.x, rey.y - 1));

    // ex update
    Func ex_updated("ex_updated");
    ex_updated(x, y) = ex_in(x, y); // start from previous ex

    // ex[i][j] for j >= 1 (x >= 1):
    //   ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])
    RDom rex(1, ex_in.dim(0).extent() - 1,  // x: 1 .. ny-1
             0, ex_in.dim(1).extent(),      // y: 0 .. nx-1
             "rex");
    ex_updated(rex.x, rex.y) =
        ex_updated(rex.x, rex.y) -
        half * (hz_in(rex.x, rex.y) - hz_in(rex.x - 1, rex.y));

    // hz update
    Func hz_updated("hz_updated");
    hz_updated(x, y) = hz_in(x, y); // start from previous hz

    // hz[i][j] for i = 0..NX-2, j = 0..NY-2 (y = 0..nx-2, x = 0..ny-2):
    //   hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j] + ey[i+1][j] - ey[i][j])
    RDom rhz(0, hz_in.dim(0).extent() - 1,  // x: 0 .. ny-2
             0, hz_in.dim(1).extent() - 1,  // y: 0 .. nx-2
             "rhz");
    hz_updated(rhz.x, rhz.y) =
        hz_updated(rhz.x, rhz.y) -
        seven_tenths *
            ((ex_updated(rhz.x + 1, rhz.y) - ex_updated(rhz.x, rhz.y)) +
             (ey_updated(rhz.x, rhz.y + 1) - ey_updated(rhz.x, rhz.y)));

    // Construct a Pipeline with three outputs: ex_updated, ey_updated, hz_updated
    Pipeline fdtd_step({ex_updated, ey_updated, hz_updated});

    // JIT-compile the pipeline once, to exclude compilation time from the measurement
    fdtd_step.compile_jit();

    // Double-buffer pointers: *curr holds the current state, *next will receive the updated state
    Halide::Buffer<num_t, 2> *ex_curr = &ex_buf_A;
    Halide::Buffer<num_t, 2> *ey_curr = &ey_buf_A;
    Halide::Buffer<num_t, 2> *hz_curr = &hz_buf_A;

    Halide::Buffer<num_t, 2> *ex_next = &ex_buf_B;
    Halide::Buffer<num_t, 2> *ey_next = &ey_buf_B;
    Halide::Buffer<num_t, 2> *hz_next = &hz_buf_B;

    // Measure only the kernel (time-stepping) execution
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tmax; ++t) {
        // Bind current buffers to ImageParams
        ex_in.set(*ex_curr);
        ey_in.set(*ey_curr);
        hz_in.set(*hz_curr);

        // Set current fictitious value
        fict_param.set(fict_buf(t));

        // Realize one time step into the "next" buffers
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next for the next iteration
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results to prevent dead-code elimination and to check correctness.
    // We mirror the original C loop order: i over rows (0..nx-1), j over columns (0..ny-1),
    // with buffer access (j, i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; ++i) {
            for (int j = 0; j < ny; ++j) {
                std::cerr << (*ex_curr)(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; ++i) {
            for (int j = 0; j < ny; ++j) {
                std::cerr << (*ey_curr)(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; ++i) {
            for (int j = 0; j < ny; ++j) {
                std::cerr << (*hz_curr)(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (like the gemm example)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
